<div id="ph-fpager" class="input-group d-flex align-items-center justify-content-center ">
  <span id="ph-fpager-first" class="btn btn-primary" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="tooltip-primary-bg" data-bs-title="First" title="First"><i class="bi bi-chevron-bar-right"></i></span>
  <span id="ph-fpager-previous" class="btn btn-primary" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="tooltip-primary-bg" data-bs-title="Previous" title="Previous"><i class="bi bi-chevron-right"></i></span>
  <span id="ph-fpager-current" class="btn btn-primary disabled" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="tooltip-primary-bg" data-bs-title="Current" title="Current">100</span>
  <span id="ph-fpager-all" class="btn btn-primary disabled" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="tooltip-primary-bg" data-bs-title="Total" title="Total">99999</span>
  <span id="ph-fpager-next" class="btn btn-primary" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="tooltip-primary-bg" data-bs-title="Next" title="Next"><i class="bi bi-chevron-left"></i></span>
  <span id="ph-fpager-last" class="btn btn-primary"><i class="bi bi-chevron-bar-left" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="tooltip-primary-bg" data-bs-title="Last" title="Last"></i></span>
</div>
